<?php
if (!defined('ABSPATH')) exit;
class TAPT_Admin {
 public function __construct(){add_action('admin_menu',[$this,'menu']);add_action('admin_post_tapt_save_result',[$this,'save_result']);add_action('admin_post_tapt_delete_draw',[$this,'delete_draw']);add_action('admin_post_tapt_import_csv',[$this,'import_csv']);}
 public function menu(){add_menu_page('TA Personal Timba','TA Personal Timba','manage_options','ta-personal-timba',[$this,'dashboard'],'dashicons-chart-line',26);add_submenu_page('ta-personal-timba','Resultados','Resultados','manage_options','tapt-results',[$this,'results']);add_submenu_page('ta-personal-timba','Agregar resultado','Agregar resultado','manage_options','tapt-add',[$this,'add']);add_submenu_page('ta-personal-timba','Importar CSV','Importar CSV','manage_options','tapt-import',[$this,'import']);add_submenu_page('ta-personal-timba','Loterías','Loterías','manage_options','tapt-lotteries',[$this,'lotteries']);add_submenu_page('ta-personal-timba','Formato CSV','Formato CSV','manage_options','tapt-csv-help',[$this,'csv_help']);do_action('tapt_admin_menu','ta-personal-timba');}
 private function notice(){if(!empty($_GET['tapt_msg']))echo '<div class="notice notice-info"><p>'.esc_html(wp_unslash($_GET['tapt_msg'])).'</p></div>';}
 public function dashboard(){global $wpdb;$t=TAPT_DB::tables();$d=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$t['draws']}");$r=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$t['results']}");echo '<div class="wrap"><h1>TA Personal Timba</h1>'; $this->notice();echo '<p>Núcleo acumulativo multi-lotería. MVP 0.1.0.</p><div class="card"><h2>Estado</h2><p><strong>'.$d.'</strong> sorteos · <strong>'.$r.'</strong> números almacenados.</p><p>Shortcode público: <code>[ta_personal_timba]</code></p></div></div>';}
 public function lotteries(){$ls=TAPT_DB::lotteries();echo '<div class="wrap"><h1>Loterías</h1><p>El MVP incluye Quini 6. La estructura ya admite múltiples loterías.</p><table class="widefat striped"><thead><tr><th>Nombre</th><th>Tipo</th><th>Rango</th><th>Números</th></tr></thead><tbody>';foreach($ls as $l)echo '<tr><td>'.esc_html($l->name).'</td><td>'.esc_html($l->game_type).'</td><td>'.sprintf('%02d–%02d',$l->number_min,$l->number_max).'</td><td>'.(int)$l->numbers_drawn.'</td></tr>';echo '</tbody></table></div>';}
 public function add(){$ls=TAPT_DB::lotteries();$l=$ls[0]??null;echo '<div class="wrap"><h1>Agregar resultado manual</h1>'; $this->notice();if(!$l){echo '<p>No hay loterías.</p></div>';return;}$mods=TAPT_DB::modalities($l->id);echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tapt_save_result">';wp_nonce_field('tapt_save_result');echo '<table class="form-table"><tr><th>Lotería</th><td><select name="lottery_id">';foreach($ls as $x)echo '<option value="'.(int)$x->id.'">'.esc_html($x->name).'</option>';echo '</select></td></tr><tr><th>Nº sorteo</th><td><input required name="contest_number"></td></tr><tr><th>Fecha</th><td><input required type="date" name="draw_date"></td></tr><tr><th>Hora</th><td><input type="time" name="draw_time"></td></tr><tr><th>Modalidad</th><td><select name="modality_id">';foreach($mods as $m)echo '<option value="'.(int)$m->id.'">'.esc_html($m->name).'</option>';echo '</select></td></tr><tr><th>Números</th><td><input required name="numbers" placeholder="07,08,23,27,40,42" class="regular-text"><p class="description">Separados por coma.</p></td></tr></table>';submit_button('Guardar resultado');echo '</form></div>';}
 public function save_result(){if(!current_user_can('manage_options')||!check_admin_referer('tapt_save_result'))wp_die('No autorizado');global $wpdb;$t=TAPT_DB::tables();$lid=absint($_POST['lottery_id']);$mid=absint($_POST['modality_id']);$contest=sanitize_text_field($_POST['contest_number']);$date=sanitize_text_field($_POST['draw_date']);$time=sanitize_text_field($_POST['draw_time']??'');$nums=array_values(array_unique(array_map('intval',preg_split('/[;,\s]+/',sanitize_text_field($_POST['numbers'])),-1,PREG_SPLIT_NO_EMPTY)));$lot=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['lotteries']} WHERE id=%d",$lid));if(!$lot||count($nums)!=(int)$lot->numbers_drawn)$this->redirect('tapt-add','Cantidad de números inválida.');foreach($nums as $n)if($n<$lot->number_min||$n>$lot->number_max)$this->redirect('tapt-add','Número fuera de rango.');$draw=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['draws']} WHERE lottery_id=%d AND contest_number=%s",$lid,$contest));if(!$draw){$wpdb->insert($t['draws'],['lottery_id'=>$lid,'contest_number'=>$contest,'draw_date'=>$date,'draw_time'=>$time?:null,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')]);$did=$wpdb->insert_id;}else{$did=$draw->id;}$existing=$wpdb->get_col($wpdb->prepare("SELECT number_value FROM {$t['results']} WHERE draw_id=%d AND modality_id=%d ORDER BY number_value",$did,$mid));$a=$nums;sort($a);$b=array_map('intval',$existing);sort($b);if($existing){if($a===$b)$this->redirect('tapt-add','Duplicado detectado: no se agregó.');$this->redirect('tapt-add','Conflicto: ese sorteo/modalidad ya existe con otros números.');}foreach($nums as $p=>$n)$wpdb->insert($t['results'],['draw_id'=>$did,'modality_id'=>$mid,'number_value'=>$n,'position'=>$p+1,'created_at'=>current_time('mysql')]);TAPT_DB::log('create','result',$did,['modality_id'=>$mid,'numbers'=>$nums]);$this->redirect('tapt-results','Resultado guardado.');}
 public function results(){global $wpdb;$t=TAPT_DB::tables();$rows=$wpdb->get_results("SELECT d.id,d.contest_number,d.draw_date,l.name lottery,GROUP_CONCAT(CONCAT(m.name,':',r.number_value) ORDER BY m.sort_order,r.number_value SEPARATOR '|') data FROM {$t['draws']} d JOIN {$t['lotteries']} l ON l.id=d.lottery_id LEFT JOIN {$t['results']} r ON r.draw_id=d.id LEFT JOIN {$t['modalities']} m ON m.id=r.modality_id GROUP BY d.id ORDER BY d.draw_date DESC,d.id DESC LIMIT 200");echo '<div class="wrap"><h1>Resultados</h1>'; $this->notice();echo '<table class="widefat striped"><thead><tr><th>Sorteo</th><th>Fecha</th><th>Lotería</th><th>Datos</th><th></th></tr></thead><tbody>';foreach($rows as $x){$url=wp_nonce_url(admin_url('admin-post.php?action=tapt_delete_draw&draw_id='.(int)$x->id),'tapt_delete_draw_'.$x->id);echo '<tr><td>'.esc_html($x->contest_number).'</td><td>'.esc_html($x->draw_date).'</td><td>'.esc_html($x->lottery).'</td><td>'.esc_html($x->data).'</td><td><a class="button-link-delete" onclick="return confirm(\'Esta operación es irreversible. ¿Eliminar el sorteo completo?\')" href="'.esc_url($url).'">Eliminar</a></td></tr>';}echo '</tbody></table></div>';}
 public function delete_draw(){$id=absint($_GET['draw_id']??0);if(!current_user_can('manage_options')||!wp_verify_nonce($_GET['_wpnonce']??'','tapt_delete_draw_'.$id))wp_die('No autorizado');global $wpdb;$t=TAPT_DB::tables();$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['draws']} WHERE id=%d",$id),ARRAY_A);$wpdb->delete($t['results'],['draw_id'=>$id]);$wpdb->delete($t['draws'],['id'=>$id]);TAPT_DB::log('delete','draw',$id,$old?:[]);$this->redirect('tapt-results','Sorteo eliminado definitivamente.');}
 public function import(){echo '<div class="wrap"><h1>Importar CSV</h1>'; $this->notice();echo '<p>Formato MVP: <code>sorteo,fecha,hora,tipo,n1,n2,n3,n4,n5,n6</code>. Tipo 1–4 para Quini 6.</p><form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="tapt_import_csv">';wp_nonce_field('tapt_import_csv');echo '<input type="file" name="csv" accept=".csv,text/csv" required>';submit_button('Importar CSV');echo '</form></div>';}
 public function import_csv(){if(!current_user_can('manage_options')||!check_admin_referer('tapt_import_csv'))wp_die('No autorizado');if(empty($_FILES['csv']['tmp_name']))$this->redirect('tapt-import','Archivo inválido.');global $wpdb;$t=TAPT_DB::tables();$lot=$wpdb->get_row("SELECT * FROM {$t['lotteries']} WHERE slug='quini6' LIMIT 1");$mods=[];foreach(TAPT_DB::modalities($lot->id) as $m)$mods[$m->code]=$m;$fh=fopen($_FILES['csv']['tmp_name'],'r');$total=$ins=$dup=$conf=$err=0;$first=true;while(($row=fgetcsv($fh,0,','))!==false){if($first){$first=false;if(isset($row[0])&&strtolower(trim($row[0]))==='sorteo')continue;}$total++;if(count($row)<10){$err++;continue;}[$contest,$date,$time,$type]=$row;$nums=array_map('intval',array_slice($row,4,6));$dateObj=DateTime::createFromFormat('d/m/Y',trim($date))?:DateTime::createFromFormat('Y-m-d',trim($date));if(!$dateObj||!isset($mods[trim($type)])||count(array_unique($nums))!==6){$err++;continue;}$valid=true;foreach($nums as $n)if($n<$lot->number_min||$n>$lot->number_max)$valid=false;if(!$valid){$err++;continue;}$draw=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['draws']} WHERE lottery_id=%d AND contest_number=%s",$lot->id,trim($contest)));if(!$draw){$wpdb->insert($t['draws'],['lottery_id'=>$lot->id,'contest_number'=>trim($contest),'draw_date'=>$dateObj->format('Y-m-d'),'draw_time'=>trim($time)?:null,'created_at'=>current_time('mysql'),'updated_at'=>current_time('mysql')]);$did=$wpdb->insert_id;}else $did=$draw->id;$mid=$mods[trim($type)]->id;$existing=array_map('intval',$wpdb->get_col($wpdb->prepare("SELECT number_value FROM {$t['results']} WHERE draw_id=%d AND modality_id=%d ORDER BY number_value",$did,$mid)));$a=$nums;sort($a);sort($existing);if($existing){if($a===$existing)$dup++;else $conf++;continue;}foreach($nums as $p=>$n)$wpdb->insert($t['results'],['draw_id'=>$did,'modality_id'=>$mid,'number_value'=>$n,'position'=>$p+1,'created_at'=>current_time('mysql')]);$ins++;}fclose($fh);$wpdb->insert($t['imports'],['filename'=>sanitize_file_name($_FILES['csv']['name']),'lottery_id'=>$lot->id,'total_rows'=>$total,'inserted_rows'=>$ins,'duplicates'=>$dup,'conflicts'=>$conf,'errors'=>$err,'user_id'=>get_current_user_id(),'created_at'=>current_time('mysql')]);TAPT_DB::log('import','csv',$wpdb->insert_id,compact('total','ins','dup','conf','err'));$this->redirect('tapt-import',"Importación: $ins nuevos, $dup duplicados, $conf conflictos, $err errores.");}
 public function csv_help(){echo '<div class="wrap"><h1>Formato CSV</h1><p>UTF-8, separado por comas y con encabezado:</p><pre>sorteo,fecha,hora,tipo,n1,n2,n3,n4,n5,n6\n3379,03/06/2026,21:15,1,07,08,23,27,40,42</pre><p><strong>Quini 6:</strong> 1 Tradicional · 2 La Segunda · 3 Revancha · 4 Siempre Sale. Pozo Extra no se importa como extracción independiente.</p></div>';}
 private function redirect($page,$msg){wp_safe_redirect(add_query_arg(['page'=>$page,'tapt_msg'=>$msg],admin_url('admin.php')));exit;}
}
